public int aggressiveCows(int[] stalls, int c) {
    Arrays.sort(stalls);
    int maxDist = stalls[stalls.length - 1] - stalls[0];
    int best = 0;
    for (int d = 1; d <= maxDist; d++) {
        if (canPlace(stalls, c, d)) {
            best = d;          // largest feasible distance so far
        } else {
            break;             // monotonic: once it fails, it always fails
        }
    }
    return best;
}

private boolean canPlace(int[] stalls, int c, int dist) {
    int count = 1, last = stalls[0];
    for (int i = 1; i < stalls.length; i++) {
        if (stalls[i] - last >= dist) {
            count++;
            last = stalls[i];
            if (count == c) return true;
        }
    }
    return count >= c;
}

