public int aggressiveCows(int[] stalls, int c) {
    Arrays.sort(stalls);
    int lo = 1, hi = stalls[stalls.length - 1] - stalls[0], ans = 0;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (canPlace(stalls, c, mid)) {
            ans = mid;        // feasible → remember it, try a BIGGER gap
            lo = mid + 1;
        } else {
            hi = mid - 1;     // infeasible → need a SMALLER gap
        }
    }
    return ans;
}

