def aggressive_cows(self, stalls: list[int], c: int) -> int:
    stalls.sort()

    def can_place(dist: int) -> bool:
        count, last = 1, stalls[0]
        for pos in stalls[1:]:
            if pos - last >= dist:
                count += 1
                last = pos
                if count == c:
                    return True
        return count >= c

    lo, hi, ans = 1, stalls[-1] - stalls[0], 0
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if can_place(mid):
            ans = mid          # feasible → remember it, try a BIGGER gap
            lo = mid + 1
        else:
            hi = mid - 1       # infeasible → need a SMALLER gap
    return ans

